"use client";
/* Room, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Room(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("room"); }, []);
  return React.createElement("piix-room", piixAttrs(props));
}

export default Room;
